329	        let mut cursor = 0;
330	        for &(len, span) in &self.0 {
331	            if (cursor..cursor + len).contains(&offset) {
332	                return (span, u16::try_from(offset - cursor).unwrap_or(0));
333	            }
334	            cursor += len;
335	        }
336	        (Span::detached(), 0)
